	if mmSaveDPoPProof.funcSaveDPoPProof != nil {
		return mmSaveDPoPProof.funcSaveDPoPProof(ctx, jti, expiresAt)
	}
	mmSaveDPoPProof.t.Fatalf("Unexpected call to StorageMock.SaveDPoPProof. %v %v %v", ctx, jti, expiresAt)
